struct string_buf { char *chars; int refs; int length; };
class stringx {
public:
  char *chars;
  string_buf *my_buf;
  stringx();
  stringx(const stringx &);
  stringx &operator=(const stringx &);
  stringx &operator=(const char *);
  ~stringx();
  int find(const char *) const;
  stringx substr(int, int) const;
  void to_lower();
  bool operator!=(const char *s) const {
    int i = 0;
    int n = my_buf->length;
    while (i < n) {
      char b = s[i];
      if (!b) return true;
      char a = my_buf->chars[i];
      if (a != b) {
        if (a < b) return true;
        if (b < a) return true;
      }
      ++i;
    }
    return s[i] != 0;
  }
};
class entity_id { public: stringx get_val() const; };
class entity { public: char pad[128]; entity_id id; stringx label; };
extern char MENUDRAW_EntityLabels[];
asm(".equ MENUDRAW_EntityLabels,0x004F5030");
stringx MENUDRAW_EntityLabel(entity *e) {
  stringx result;
  result = e->label;
  if (result != MENUDRAW_EntityLabels) {
  } else {
    result = e->id.get_val();
    if (result != MENUDRAW_EntityLabels) {
    } else {
      result = "Unknown";
    }
  }
  if (result.find("_ENTID_") == 0)
    result = result.substr(7, -1);
  int pos = result.find("_");
  if (pos >= 0)
    result = result.substr(pos + 1, -1);
  result.to_lower();
  return result;
}
